import json, os, math

logdir = '/root/autodl-tmp/event-gated-adaptive-horizon/logdir'

experiments = {
    'exp_001_baseline': {'dir': 'baseline_s1', 'type': 'healthy', 'desc': 'baseline'},
    'exp_008a': {'dir': 'exp_008a_fixed_dt2_no_subsample', 'type': 'healthy', 'desc': 'untrained dt_emb, V-recovery'},
    'exp_008c': {'dir': 'exp_008c_fixed_dt2_no_subsample_h8', 'type': 'healthy', 'desc': 'plateau, no collapse'},
    'exp_008d': {'dir': 'exp_008d_subsample_on_h8', 'type': 'collapsed', 'desc': 'trained dt_emb, delusional critic'},
    'exp_006': {'dir': 'fixed_dt2_v1_s1', 'type': 'collapsed', 'desc': 'trained dt_emb, collapse'},
    'exp_008f': {'dir': 'exp_008f_no_dt_embed_subsample_on_h8', 'type': 'healthy', 'desc': 'dt_embed_dim=0, C2 control'},
    'exp_008e_v3': {'dir': 'exp_008e_v3_subsample_on_dt1_h15', 'type': 'healthy', 'desc': 'B+ confound'},
}

result = {'metadata': {'generated': '2026-05-14', 'description': 'Actor entropy + value calibration analysis'}, 'experiments': {}}

for exp_id, info in experiments.items():
    fpath = os.path.join(logdir, info['dir'], 'metrics.jsonl')
    if not os.path.exists(fpath):
        result['experiments'][exp_id] = {'error': 'metrics.jsonl not found'}
        continue

    train_lines = []  # lines with actor_entropy
    env_lines = []    # lines with train_return

    with open(fpath) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            if 'actor_entropy' in d:
                train_lines.append(d)
            elif 'train_return' in d:
                env_lines.append(d)

    # Build train_return lookup by step
    tr_by_step = {int(e['step']): e['train_return'] for e in env_lines}

    # Extract trajectories
    entropy_traj = []
    value_cal_traj = []

    for t in train_lines:
        step = int(t['step'])
        ae = t['actor_entropy']
        vm = t['value_mean']
        vs = t.get('value_std', None)
        tm = t.get('target_mean', None)
        al = t.get('actor_loss', None)

        entropy_traj.append({'step': step, 'actor_entropy': round(ae, 4), 'actor_loss': round(al, 4) if al else None})

        # Find closest train_return
        closest_step = min(tr_by_step.keys(), key=lambda s: abs(s - step)) if tr_by_step else None
        tr = tr_by_step.get(closest_step) if closest_step and abs(closest_step - step) <= 5000 else None

        ve_ratio = vm / tr if tr and tr > 1.0 else None

        value_cal_traj.append({
            'step': step,
            'value_mean': round(vm, 2),
            'value_std': round(vs, 2) if vs else None,
            'target_mean': round(tm, 2) if tm else None,
            'train_return': round(tr, 2) if tr else None,
            'v_over_return': round(ve_ratio, 4) if ve_ratio else None,
            'v_over_target': round(vm / tm, 4) if tm and abs(tm) > 0.01 else None,
        })

    result['experiments'][exp_id] = {
        'type': info['type'],
        'desc': info['desc'],
        'logdir': info['dir'],
        'n_train_points': len(train_lines),
        'n_env_points': len(env_lines),
        'step_range': [train_lines[0]['step'], train_lines[-1]['step']] if train_lines else [],
        'actor_entropy_trajectory': entropy_traj,
        'value_calibration_trajectory': value_cal_traj,
    }

# Compute normalized v/e ratios (relative to baseline at same step)
baseline_ve = {}
if 'exp_001_baseline' in result['experiments']:
    for pt in result['experiments']['exp_001_baseline']['value_calibration_trajectory']:
        if pt['v_over_target'] is not None:
            baseline_ve[pt['step']] = pt['v_over_target']

for exp_id, data in result['experiments'].items():
    if exp_id == 'exp_001_baseline' or 'error' in data:
        continue
    normalized = []
    for pt in data['value_calibration_trajectory']:
        step = pt['step']
        # find closest baseline step
        if baseline_ve:
            closest = min(baseline_ve.keys(), key=lambda s: abs(s - step))
            if abs(closest - step) <= 5000 and pt['v_over_target'] is not None:
                norm = pt['v_over_target'] / baseline_ve[closest]
                label = 'normal' if 0.8 <= norm <= 1.2 else ('suppressed' if norm < 0.7 else ('pathological' if norm > 1.5 else 'borderline'))
                normalized.append({'step': step, 'normalized_vt_ratio': round(norm, 4), 'label': label})
    data['normalized_value_calibration'] = normalized

# Summary statistics
summary = {'actor_entropy': {}, 'value_calibration': {}}
for exp_id, data in result['experiments'].items():
    if 'error' in data:
        continue
    ent = data['actor_entropy_trajectory']
    if ent:
        early = [e['actor_entropy'] for e in ent if e['step'] <= 15000]
        late = [e['actor_entropy'] for e in ent if e['step'] >= max(e2['step'] for e2 in ent) - 10000]
        summary['actor_entropy'][exp_id] = {
            'type': data['type'],
            'early_mean': round(sum(early)/len(early), 3) if early else None,
            'late_mean': round(sum(late)/len(late), 3) if late else None,
            'total_change': round(late[-1] - early[0], 3) if early and late else None,
        }

    cal = data.get('normalized_value_calibration', data['value_calibration_trajectory'])
    if cal and 'normalized_vt_ratio' in cal[0] if cal else False:
        late_cal = [c for c in cal if c['step'] >= max(c2['step'] for c2 in cal) - 10000]
        summary['value_calibration'][exp_id] = {
            'type': data['type'],
            'late_normalized_vt': round(sum(c['normalized_vt_ratio'] for c in late_cal)/len(late_cal), 4) if late_cal else None,
            'late_label': late_cal[-1]['label'] if late_cal else None,
        }
    else:
        vt = data['value_calibration_trajectory']
        if vt:
            late_vt = [v for v in vt if v['step'] >= max(v2['step'] for v2 in vt) - 10000]
            summary['value_calibration'][exp_id] = {
                'type': data['type'],
                'late_v_over_target': round(sum(v['v_over_target'] for v in late_vt if v['v_over_target'])/max(1,sum(1 for v in late_vt if v['v_over_target'])), 4) if late_vt else None,
            }

result['summary'] = summary

outpath = os.path.join(logdir, 'analysis_actor_entropy_value_calibration.json')
with open(outpath, 'w') as f:
    json.dump(result, f, indent=2)

print(f'Written to {outpath}')
print(f'File size: {os.path.getsize(outpath)} bytes')
print()
print('=== ACTOR ENTROPY SUMMARY ===')
for eid, s in summary['actor_entropy'].items():
    print(f'{eid:25s} [{s[\"type\"]:9s}] early={s[\"early_mean\"]:8.3f}  late={s[\"late_mean\"]:8.3f}  change={s[\"total_change\"]:8.3f}')

print()
print('=== VALUE CALIBRATION SUMMARY ===')
for eid, s in summary['value_calibration'].items():
    if 'late_normalized_vt' in s:
        print(f'{eid:25s} [{s[\"type\"]:9s}] norm_v/t={s[\"late_normalized_vt\"]:7.4f}  label={s[\"late_label\"]}')
    elif 'late_v_over_target' in s:
        print(f'{eid:25s} [{s[\"type\"]:9s}] v/t={s[\"late_v_over_target\"]:7.4f} (baseline, unnormalized)')
"

